insert into regras_globais (id, versao, regras) values (1, '2026-11-14', '{"prioridade": "Sempre prevalece sobre presets antigos e sobre o DNA de qualquer cliente.", "fidelidade_midia": ["Preservar o vídeo como capturado: cor, contraste, exposição, iluminação, textura, pele, rosto, corpo, enquadramento e características reais", "Proibido: filtro de beleza, suavização facial, retoque, tratamento de pele, LUT criativa, nitidez artificial, melhoria automática de cor, coloração gerativa", "Proibido alterar produto, pessoa, marca ou frota", "Inspecionar cada original com ffprobe (resolução, fps, HDR/SDR, primárias, transferência) e manter o gerenciamento de cor do original do início ao fim; HDR continua HDR"], "render": {"fonte": "Arquivos originais, geralmente 4K/30 fps", "previa": "480p (altura 854) renderizada a partir do original, mesma colorimetria", "final": "Após aprovação, renderizar de novo a partir dos arquivos originais na resolução e fps nativos (4K/30 quando for o caso). Nunca ampliar a prévia", "entrega_final": ["vídeo final", "versão sem legenda", "legendas .srt", "capa"]}, "edicao_permitida": ["Cortes de pausas, vícios e erros de fala", "Reordenação narrativa de falas sem distorcer contexto e sem inventar ou montar falas", "Legendas, títulos e destaques", "Transições com função", "Reframing geométrico discreto (crop/zoom), sem tocar na imagem", "Tratamento de voz quando necessário"], "audio": "Sem música automática; trilha e efeitos sonoros entram depois, com a Bora", "identidade": "O app usa azul #072740, laranja #FF5E16 e bege #F2EADF. Cada vídeo segue a identidade do próprio cliente, sem herdar estilo de outro cliente", "dna_alteracoes": "Feedback de uma versão fica registrado na versão. Após aprovação o sistema pode sugerir atualizações do DNA; regra permanente só muda com confirmação explícita do usuário", "referencias": "Carregar referências aprovadas reais acessíveis no Drive e marcar se já foram analisadas; nunca presumir análise"}'::jsonb) on conflict (id) do update set versao=excluded.versao, regras=excluded.regras, atualizado_em=now();
