insert into dna_versoes (cliente_id, numero, dna, motivo) values ('fabiola', 1, '{"ritmo_resumo": "Médio, com breves acelerações", "essencia": "Autoridade médica humana, didática, confiável e próxima. Linguagem de Reels/TikTok sem banalização", "tom": "Conversacional, calma, segura, acessível, curiosa, nunca alarmista", "storytelling": "Gancho provocativo fiel à fala, identificação da dúvida, explicação com analogia concreta, virada médica, orientação segura", "ganchos": ["Pergunta que desafia crença comum e será respondida no vídeo", "Conexão inesperada entre hábitos e rins", "Cena de objeto real com fala curta gerando curiosidade"], "edicao": ["Cortar pausas excessivas com naturalidade", "Zoom muito sutil em revelações, nunca constante", "Manter objetos e analogias na tela pelo tempo necessário para compreender", "Ritmo médio com breves acelerações"], "legendas_identidade": ["Fonte limpa de padrão médico premium", "Frases curtas; destaques moderados, nunca poluição visual", "Linguagem visual parte das capas e referências realmente aprovadas", "Azul-marinho, areia/bege, cinza e branco como referência observada; usar os arquivos da marca"], "evitar": ["Efeitos infantis", "Sustos médicos e sensacionalismo", "Imagens fictícias apresentadas como exames verdadeiros", "Afirmações clínicas não presentes no material", "CTA comercial insistente", "Suavização facial, filtros e gradação artificial"], "duracao": "30 a 60 s, salvo briefing diferente (os aprovados tiveram 64 s e 101 s)", "paleta": {"cores": ["#C8B9A7", "#8FB0D8", "#0F1C4A", "#FFFFFF"], "origem": "observada_em_aprovados"}, "texto": {"legenda": "#FFFFFF", "destaque": "#C8B9A7", "origem": "aprovado"}, "padroes_extraidos": {"fonte": "Análise da Bora sobre os vídeos aprovados (Energéticos, Diabetes) e as 4 referências da cliente no Drive", "itens": [["Ritmo de fala", "137 a 155 palavras/min, voz natural sem acelerar"], ["Cortes", "Pausas acima de 0,30 s cortadas (limiar -45 dB), mantendo 0,10 s; nunca cortar final de palavra"], ["Gancho", "Pergunta curiosa logo no 1º segundo, sem ''olá'' nem ''agora eu vou falar''"], ["Título", "Na altura do peito, sem caixa, degradê escuro suave; 3 linhas com a mesma largura: rótulo espaçado Poppins Medium, tema Merriweather Black Italic, pergunta Poppins SemiBold branca; entra subindo 18 px com fade em cascata; fica 3 a 5 s"], ["Legenda", "Minimal, branca forte, minúscula, sem pontos, sombra ~35%, 2 a 4 palavras, acima da interface do Reels"], ["Destaques", "3 a 4 por vídeo, linhas coladas, palavra principal em creme #C8B9A7; variar Poppins pop, serifa itálica e lettering letra a letra"], ["Palavra solta", "2 a 3 por vídeo: só a palavra-chave, grande, serifa itálica creme, na posição dos letterings"], ["B-roll", "Objetos 3D recortados entrando pela lateral; quando animado, vídeo de verdade (ex.: canal se fechando), nunca imagem deslizando"], ["Analogias", "Objeto real em cena (coador de café, canudinho) com tempo para compreender"], ["Finalização Bora", "Trilha contínua abaixo da voz, SFX nas entradas de elementos, 1 transição de luz na virada de assunto"]]}, "regras_confirmadas": ["Gancho direto na pergunta, sem ''agora eu vou falar''", "B-roll animado é vídeo de verdade, não imagem deslizando", "Branco da legenda forte, nada acinzentado", "Nunca cortar final de palavra"]}'::jsonb, 'Importado de bora_studio_dna_clientes.json') on conflict do nothing;
