insert into dna_versoes (cliente_id, numero, dna, motivo) values ('fagtransportes', 1, '{"ritmo_resumo": "Corporativo e cinematográfico sóbrio", "essencia": "Segurança, pontualidade, operação estruturada, atendimento humano e credibilidade", "tom": "Institucional contemporânea, objetiva, segura, com histórias reais de clientes e rotas quando houver", "storytelling": "Contexto real, necessidade de mobilidade, estrutura, equipe e cuidado, entrega confiável, convite a orçamento", "ganchos": ["Dimensão da operação com dado confirmado", "Veículo e equipe reais em ação", "Jornada de transporte pelo ponto de vista do passageiro"], "edicao": ["Ritmo médio e cinematografia sóbria", "Veículos reais, motorista, interior, embarque, rota e atendimento", "Cortes suaves, sem transição caricata", "Identificação correta da frota"], "legendas_identidade": ["Indicadores corporativos só se revalidados", "Tipografia clean e títulos objetivos", "Preto, branco e turquesa conforme o folder recente, respeitando a marca atual", "Logo nova só quando fornecida e aprovada; não modificar a pintura real dos veículos"], "evitar": ["Imagens genéricas de frota que não seja da FAG sem rotular", "Criar vans ou ônibus inexistentes", "Trocar logotipos reais nas carrocerias", "Inventar números de frota, cidades, acidentes ou segurança", "Efeitos brilhantes e cor artificial", "Filtros ou retoque das pessoas"], "duracao": "20 a 70 s, salvo briefing diferente", "paleta": {"cores": ["#000000", "#FFFFFF", "#1FB5AC"], "origem": "observada_validar"}, "texto": {"legenda": "#FFFFFF", "destaque": null, "origem": "pendente"}, "referencias_conhecidas": ["Folder institucional, imagem real dos veículos alinhados, portfólio e nova logo enviada"], "pendencias": ["Logo vigente aprovada", "Vídeos reais aprovados"], "regras_confirmadas": []}'::jsonb, 'Importado de bora_studio_dna_clientes.json') on conflict do nothing;
